use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let path_str = input.as_str().unwrap();
    let mut path = path_str.to_string();
    let mut last = None;

    for c in path.chars() {
        if c == '/' {
            if let Some(last) = last {
                path = format!("{}/{}", last, c);
            } else {
                path = format!("{}/{}", c, path);
            }
        } else if c == '.' {
            if let Some(last) = last {
                path = format!("{}/{}", last, c);
            } else {
                path = format!("{}/{}", c, path);
            }
        } else if c == '..' {
            if let Some(last) = last {
                path = format!("{}/{}", last, c);
            } else {
                if path == "/" {
                    path = String::from("/");
                } else {
                    path = format!("{}/{}", path, "..");
                }
            }
        } else {
            last = Some(c);
        }
    }

    Value::String(path)
}
